// ProductCardGlass.jsx
import React, { useState } from "react";
import styled from "styled-components";
const zen = "/about.jpg";

const CardScene = styled.div`
  width: ${(props) => props.$width};
  height: ${(props) => props.$height};
  perspective: 1000px;
  cursor: ${(props) => props.$cursor};

  &:hover .productCardGlass__card,
  &:focus-visible .productCardGlass__card {
    transform: rotateY(180deg);
  }
`;

const FlipCard = styled.div`
  position: relative;
  width: 100%;
  height: 100%;
  transform: ${(props) => (props.$flipped ? "rotateY(180deg)" : "rotateY(0)")};
  transform-style: preserve-3d;
  transition: transform 800ms ease;
`;

const CardFace = styled.div`
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 0.5rem;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.45);
`;

const FrontFace = styled(CardFace)`
  color: rgba(0, 0, 0, 0.89);
  background-image: url(${zen});
  background-position: center;
  background-size: cover;
`;

const BackFace = styled(CardFace)`
  transform: rotateY(180deg);
  background: #404040;
  border: 1px solid rgba(255, 255, 255, 0.1);
`;

const FrontPanel = styled.div`
  width: 60%;
  padding: 1rem;
  border-radius: 0.5rem;
  background: rgba(255, 255, 255, 0.3);
  backdrop-filter: blur(5px);
  text-align: center;

  h3 {
    margin: 0 0 0.5rem;
  }

  p {
    margin: 0;
  }
`;

const BackContent = styled.div`
  width: 80%;

  h3 {
    margin: 0 0 0.5rem;
  }

  p {
    margin: 0;
    font-size: 0.75rem;
  }
`;

function ProductCardGlass({
  width = "300px",
  height = "200px",
  cursor = "pointer",
  primaryColor = "rgba(255,255,255,.89)",
  secondaryColor = "rgba(255,255,255,.6)",
}) {
  const [flipped, setFlipped] = useState(false);

  const toggleCard = () => setFlipped((isFlipped) => !isFlipped);

  const handleKeyDown = (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      toggleCard();
    }
  };

  return (
    <CardScene
      className="productCardGlass"
      $width={width}
      $height={height}
      $cursor={cursor}
      role="button"
      tabIndex={0}
      aria-label="Flip 3D visualization card"
      aria-pressed={flipped}
      onClick={toggleCard}
      onKeyDown={handleKeyDown}
    >
      <FlipCard
        className="productCardGlass__card"
        $flipped={flipped}
      >
        <FrontFace
          className="productCardGlass__card__blur__front"
        >
          <FrontPanel>
            <h3>@learnMern</h3>
            <p>React Developer</p>
          </FrontPanel>
        </FrontFace>
        <BackFace
          className="productCardGlass__card__blur__back"
        >
          <BackContent>
            <h3 style={{ color: primaryColor }}>
              React Developer
            </h3>
            <p style={{ color: secondaryColor }}>
              Lorem ipsum dolor sit amet, verear fabellas corrumpit vix no, ne
              has omnis sanctus sensibus, prima nihil meliore ad per. Est cu
              qualisque persecuti. Autem imperdiet gubergren sed ne, an.
            </p>
          </BackContent>
        </BackFace>
      </FlipCard>
    </CardScene>
  );
}

export default ProductCardGlass;
